use fereg_core::ppml::{estimate_ppml_memory, plan_ppml_memory, PpmlMemoryConfig, PpmlMemoryDimensions};
use fereg_core::options::MemoryMode;
    fn dimensions() -> PpmlMemoryDimensions {
        PpmlMemoryDimensions {
            metadata: Default::default(),
            observations: 100_000,
            original_observations: 100_000,
            candidate_observations: 100_000,
            loaded_numeric_columns: 6,
            retained_base_adjustment_capacity_elements: 0,
            retained_raw_preseparation_probability_weight_elements: 0,
            finite_columns: 20,
            coefficient_slots: 20,
            reported_coefficient_slots: 20,
            fe_dimensions: 2,
            fe_total_levels: 30_000,
            fe_max_levels: 20_000,
            fe_total_channels: 2,
            fe_max_channels: 1,
            fe_max_level_members: 20,
            fe_coefficient_directions: 30_000,
            fe_max_effect_directions: 20_000,
            cluster_dimensions: 2,
            cluster_subset_groups: 35_000,
            separation_workspace_vectors: 8,
            separation_singleton_enabled: true,
            separation_method_count: 4,
            separation_generation_capacity: 100_000,
            separation_rebase_enabled: true,
            separation_exact_fe_enabled: true,
            separation_mu_enabled: false,
            simplex_tableau_cells: 1_000_000,
            requested_output_columns: 0,
            requested_mean_output: false,
            requested_saved_fe_channels: 0,
            publication_matrix_cells: 2_000,
            threads: 4,
            allocation_audit_enabled: false,
        }
    }

fn main() {
 eprintln!("sizes certificate={} observation={} telemetry={}",std::mem::size_of::<fereg_core::ppml::PpmlSteadyStateAllocationCertificate>(),std::mem::size_of::<fereg_core::ppml::PpmlSteadyStateAllocationObservation>(),std::mem::size_of::<fereg_core::ppml::PpmlMemoryTelemetry>());
 let mut id=0;
 for n in [0,1,127,128,4095,4096,16383,16384,100000] {
  for k in [0,1,5,20,63,64,65,200000] {
   for threads in [1,4,8,16] {
    for effects in 0..=5 {
     if n==0 && effects>0 {continue;}
     let mut d=dimensions();
     d.observations=n; d.original_observations=n+31; d.candidate_observations=n+11;
     d.finite_columns=k; d.coefficient_slots=k; d.reported_coefficient_slots=k+7;
     d.threads=threads; d.fe_dimensions=effects;
     let levels=if effects==0 {0} else {n.min(11)};
     d.fe_total_levels=levels*effects; d.fe_max_levels=levels;
     let channels=if effects==5 {2} else {1};
     d.fe_total_channels=effects*channels; d.fe_max_channels=if effects==0 {0} else {channels};
     d.fe_max_level_members=if effects==0 {0} else {n.min(13)};
     d.fe_coefficient_directions=d.fe_total_levels*channels;
     d.fe_max_effect_directions=levels*channels;
     d.cluster_subset_groups=n.min(23)*3;
     d.separation_generation_capacity=n.max(2);
     d.retained_base_adjustment_capacity_elements=if id%2==0 {0} else {d.candidate_observations};
     d.retained_raw_preseparation_probability_weight_elements=if id%3==0 {0} else {n};
     d.allocation_audit_enabled=id%2==0;
     d.separation_mu_enabled=id%7==0;
     d.requested_saved_fe_channels=if id%4==0 {d.fe_total_channels} else {0};
     d.requested_mean_output=id%3==0;
     d.requested_output_columns=d.requested_saved_fe_channels+usize::from(d.requested_mean_output)+1;
     d.metadata.input_owner_bytes=id as u128;
     for pool in [1,4,10] { println!("{id}|ols|{pool}|{:?}",fereg_core::memory::estimate_phase2_memory(n,6,k,effects,2,pool).unwrap()); }
     let c=PpmlMemoryConfig{poolsize:[1,4,10][id%3],diagnostic_capacity:[0,1,32][id%3],embedding_resident_bytes:id as u128*13,..Default::default()};
     let e=match estimate_ppml_memory(d,c) {Ok(e)=>e,Err(e)=>{println!("{id}|estimate-error|{:?}",e.code);id+=1;continue;}};
     println!("{id}|estimate|{e:?}");
     for route in [MemoryMode::Fast,MemoryMode::Low,MemoryMode::Auto] {
      let peak=match route {MemoryMode::Fast=>e.fast.peak_bytes,_=>e.low.peak_bytes};
      let available=(peak+512*1024*1024).max((peak*5).div_ceil(4));
      for budget in [None,Some(available),Some(available-1)] {
       let config=PpmlMemoryConfig{requested:route,available_bytes:budget,..c};
       match plan_ppml_memory(d,config) {
        Ok(plan)=>println!("{id}|plan|{route:?}|{budget:?}|{plan:?}"),
        Err(e)=>println!("{id}|error|{route:?}|{budget:?}|{:?}",e.code),
       }
      }
     }
     id+=1;
    }
   }
  }
 }
 eprintln!("cases={id}");
}
